async function check_content(aWindow, aExpected, aDontWantToSee) {
  const messageContent = await SpecialPowers.spawn(
    get_about_message(aWindow).getMessagePaneBrowser(),
    [],
    function () {
      return content.document.documentElement.textContent;
    }
  );

  if (aExpected != aDontWantToSee) {
    Assert.ok(
      messageContent.includes(aExpected),
      "Didn't find expected content"
    );
    Assert.ok(
      !messageContent.includes(aDontWantToSee),
      "Found content that shouldn't be there"
    );
  } else {
    const ind = messageContent.indexOf(aExpected);
    Assert.greaterOrEqual(ind, 0, "Didn't find expected content");
    if (ind >= 0) {
      Assert.ok(
        !messageContent.substr(ind + aExpected.length).includes(aExpected),
        "Found content a second time"
      );
    }
  }
}
